import React from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../auth/AuthContext';

export default function Navbar() {
  const { user, logout } = useAuth();
  const navigate = useNavigate();

  return (
    <nav style={{
      display: 'flex',
      justifyContent: 'space-between',
      alignItems: 'center',
      padding: '16px 40px',
      background: '#FFFFFF',
      borderBottom: '1px solid #E2E8F0',
      boxShadow: '0 1px 3px rgba(0,0,0,0.02)',
      position: 'sticky',
      top: 0,
      zIndex: 100
    }}>
      <div style={{ fontSize: '18px', fontWeight: 'bold' }}>
        <Link to="/" style={{ color: '#2563EB', textDecoration: 'none', display: 'flex', alignItems: 'center', gap: '8px' }}>
          🎓 <span style={{ color: '#1E293B' }}>UniEquipment</span>
        </Link>
      </div>

      <div style={{ display: 'flex', alignItems: 'center', gap: '24px' }}>
        <Link to="/" style={{ color: '#64748B', textDecoration: 'none', fontWeight: '500', fontSize: '14px' }}>หน้าแรก</Link>

        {user.role === 'member' && (
          <Link to="/my-borrowings" style={{ color: '#64748B', textDecoration: 'none', fontWeight: '500', fontSize: '14px' }}>ประวัติการยืม</Link>
        )}

        {user.role === 'admin' && (
          <Link to="/admin" style={{ color: '#2563EB', textDecoration: 'none', fontWeight: '600', fontSize: '14px' }}>
            🛡️ จัดการหลังบ้าน
          </Link>
        )}

        {user.role === 'guest' ? (
          <div style={{ display: 'flex', gap: '12px' }}>
            <Link to="/login" style={{
              background: '#EFF6FF',
              color: '#2563EB',
              padding: '8px 16px',
              borderRadius: '8px',
              textDecoration: 'none',
              fontWeight: '600',
              fontSize: '14px'
            }}>
              เข้าสู่ระบบ
            </Link>
            <Link to="/register" style={{
              background: '#2563EB',
              color: '#FFFFFF',
              padding: '8px 16px',
              borderRadius: '8px',
              textDecoration: 'none',
              fontWeight: '600',
              fontSize: '14px'
            }}>
              สมัครสมาชิก
            </Link>
          </div>
        ) : (
          <div style={{ display: 'flex', alignItems: 'center', gap: '16px' }}>
            <span style={{ fontSize: '14px', color: '#64748B' }}>
              👤 {user.name} (<strong style={{ color: '#2563EB' }}>{user.role}</strong>)
            </span>
            <button 
              onClick={() => { logout(); navigate('/'); }}
              style={{
                background: '#Ffeeec',
                color: '#EF4444',
                border: 'none',
                padding: '6px 12px',
                borderRadius: '6px',
                cursor: 'pointer',
                fontWeight: '600',
                fontSize: '13px'
              }}
            >
              ออกจากระบบ
            </button>
          </div>
        )}
      </div>
    </nav>
  );
}
